use vstd::prelude::*;

verus! {

spec fn max_nat(a: nat, b: nat) -> nat {
    if a >= b { a } else { b }
}

fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> (res: Vec<char>)
    ensures
        // length is max(orig.len, width)
        res@.len() == max_nat(orig@.len(), width as nat),

        // if no padding needed, result is exactly original
        orig@.len() >= width as nat ==> res@ == orig@,

        // if padding needed, original appears as a suffix and prefix is fillchar
        orig@.len() < width as nat ==>
            res@.len() == width as nat
            && res@.subrange((width as nat - orig@.len()) as int, width as int) == orig@
            && (forall|i: int|
                    0 <= i < (width as nat - orig@.len()) as int
                    ==> res@[i] == fillchar),

        // explicit empty-orig case (implied by the above, but stated as requested)
        orig@.len() == 0 ==> res@.len() == width as nat,
{
    let n: usize = orig.len();
    let w: usize = width as usize;

    if n >= w {
        // unchanged
        orig
    } else {
        let pad: usize = w - n;

        let mut res: Vec<char> = Vec::new();
        let mut i: usize = 0;

        // push pad copies of fillchar
        while i < pad
            invariant
                i <= pad,
                res@.len() == i as nat,
                forall|k: int| 0 <= k < i as int ==> res@[k] == fillchar,
            decreases pad - i,
        {
            res.push(fillchar);
            i = i + 1;
        }

        let mut j: usize = 0;
        // append orig
        while j < n
            invariant
                j <= n,
                res@.len() == (pad + j) as nat,
                // prefix stays fillchar
                forall|k: int| 0 <= k < pad as int ==> res@[k] == fillchar,
                // suffix built so far matches orig prefix of length j
                res@.subrange(pad as int, (pad + j) as int) == orig@.subrange(0, j as int),
            decreases n - j,
        {
            res.push(orig[j]);
            j = j + 1;
        }

        // Conclude full suffix equals orig
        assert(res@.subrange(pad as int, (pad + n) as int) == orig@) by {
            assert(orig@.subrange(0, n as int) == orig@);
        }

        res
    }
}

} // verus!

